const upsertPermission = `-- name: UpsertPermission :one

INSERT INTO rbac.permissions (key, description)
VALUES ($1, $2)
ON CONFLICT (key) DO UPDATE SET description = EXCLUDED.description
RETURNING id, key, description
`

type UpsertPermissionParams struct {
	Key         string
	Description string
}

// Queries for the rbac domain. All queries are sqlc-generated, including the two
// awkward ones: AssignRoleToGroup (a conditional CTE INSERT whose RETURNING is
// folded into an EXISTS check, returning a single bool) and ExplainGrants (a
// two-armed UNION ALL with typed NULL columns for the direct arm).
func (q *Queries) UpsertPermission(ctx context.Context, arg UpsertPermissionParams) (RbacPermission, error) {
	row := q.db.QueryRow(ctx, upsertPermission, arg.Key, arg.Description)
	var i RbacPermission
	err := row.Scan(&i.ID, &i.Key, &i.Description)
	return i, err
}

const usersWithPermission = `-- name: UsersWithPermission :many
SELECT DISTINCT holder.user_id
FROM (
    SELECT ur.user_id
    FROM rbac.user_roles ur
    JOIN rbac.role_permissions rp ON rp.role_id = ur.role_id
    JOIN rbac.permissions p ON p.id = rp.permission_id
    WHERE ur.organization_id = $1 AND p.key = $2
    UNION
    SELECT gm.user_id
    FROM organization.group_members gm
    JOIN rbac.group_roles gr ON gr.group_id = gm.group_id AND gr.organization_id = gm.organization_id
    JOIN rbac.role_permissions rp ON rp.role_id = gr.role_id
    JOIN rbac.permissions p ON p.id = rp.permission_id
    WHERE gm.organization_id = $1 AND p.key = $2
) holder
JOIN account.users u ON u.id = holder.user_id AND u.deleted_at IS NULL AND u.status = 'active'
LIMIT 200
`

type UsersWithPermissionParams struct {
	OrganizationID uuid.UUID
	PermKey        string
}

// UsersWithPermission lists the active members of the organization who hold the
// permission, directly or through a group: the people to tell about something
// only they can act on, such as an access request.
func (q *Queries) UsersWithPermission(ctx context.Context, arg UsersWithPermissionParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, usersWithPermission, arg.OrganizationID, arg.PermKey)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var user_id uuid.UUID
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
